@Service
public class UserRegistrationService {

    public void register(UserForm form) {
        if (form.email() == null || !form.email().contains("@")) {
            throw new IllegalArgumentException("invalid email");
        }
        User user = new User(form.email(), form.name());

        jdbcTemplate.update(
            "INSERT INTO users(email, name) VALUES (?, ?)", user.email(), user.name());

        SimpleMailMessage welcome = new SimpleMailMessage();
        welcome.setTo(user.email());
        welcome.setSubject("Welcome");
        mailSender.send(welcome);

        auditLog.record("USER_REGISTERED", user.email(), Instant.now());
    }
}
